-- Accept the standard UUID generated by the form and previously accepted legacy keys.
ALTER TABLE public.referrals
  DROP CONSTRAINT referrals_offline_submission_key_required,
  ADD CONSTRAINT referrals_offline_submission_key_required CHECK (
    sync_source IS DISTINCT FROM 'offline' OR (
      referring_user_id IS NOT NULL AND offline_client_id IS NOT NULL AND
      offline_client_id ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3,4}-[0-9a-f]{12}$'
    )
  );
